import Foundation

nonisolated enum BBCapability: String, Codable {
 
    case automated
    case runtime
    case partial
    case manual
    case unavailable
    case onHold
}

nonisolated enum BBRuleType: String, Codable {
    case fail = "Fail"
    case pass = "Pass"
    case validate = "Validate"
}

nonisolated struct BBRule: Codable, Hashable {
    let id: String
    let element: String
    let issue: String
    let type: BBRuleType
    let wcag: String
    let level: String
    let severity: String
    let ios: BBCapability
    let android: BBCapability
    /// Flutter exposes less than native for this rule (see note).
    let flutterLimited: Bool
    /// Review or duplicate codes whose check the scanner reports under these
    /// sibling codes instead (a verdict rather than a review).
    let coveredBy: [String]
    let note: String

    func capability(on platform: MobilePlatform) -> BBCapability {
        platform == .android ? android : ios
    }
}

